// saas/app/api/cos-primary/route.ts
// Live COS-first entrypoint. Provenance fields in this route are assembled from
// execution state, never generated by a model.

import { NextRequest, NextResponse } from 'next/server'
import { POST as legacyConciergePost } from '@/app/api/concierge/route'
import { tryCOSFirstAnswer } from '@/lib/ai/cos/cosFirstAnswer'
import { tryDeterministicUtility } from '@/lib/ai/cos/deterministicUtilities'
import { resolveCosReasoner } from '@/lib/ai/cos/cosReasoner'
import { checkLocalInferenceHealth, localInferenceConfigFromEnv } from '@/lib/ai/local-inference'
import { getAccess } from '@/lib/auth/access'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'
export const maxDuration = 300

function latestUserText(body: any): string {
  const messages = Array.isArray(body?.messages) ? body.messages : []
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    if (messages[i]?.role !== 'user') continue
    const content = messages[i]?.content
    if (typeof content === 'string') return content
    if (Array.isArray(content)) return content.map((block: any) => String(block?.text || '')).join('\n').trim()
  }
  return ''
}

function languageFrom(body: any): string {
  const value = String(body?.context?.language || 'en').toLowerCase()
  return ['en', 'es', 'pt', 'pl', 'ru'].includes(value) ? value : 'en'
}

function confidenceThreshold(): number {
  const value = Number(process.env.COS_LOCAL_CONFIDENCE_THRESHOLD || '0.72')
  return Number.isFinite(value) ? Math.max(0.5, Math.min(0.98, value)) : 0.72
}

function externalFallbackEnabled(): boolean {
  return process.env.COS_EXTERNAL_AI_FALLBACK_ENABLED !== 'false'
}

function isProvenanceIntrospection(input: string): boolean {
  const provenance = /\b(provenance|introspection|execution provenance|execution telemetry|audit trail|model contribution|model contributions|which model|what model|primary model|reasoner|semantic cache|enterprise memory|knowledge graph|learned corpus|learning corpus|autonomous research|external ai|external provider|internal systems?)\b/i
  const referent = /\b(previous|preceding|prior|last|just|that|this|answer|response|request|execution|used|invoked|contributed|generated|reasoning)\b/i
  return provenance.test(input) && referent.test(input)
}

function requestsExternalAction(input: string): boolean {
  if (isProvenanceIntrospection(input)) return false
  const explicitExecution = /\b(run|execute|perform|investigate|check|fetch|pull|read|scan|audit|search|look up|research|deploy|commit|merge|create|update|delete|send|publish|queue|launch|start|fix|repair|change|modify|call the tool|use (?:the )?tools?)\b/i
  const target = /\b(repo|repository|github|vercel|supabase|logs?|metrics?|status page|production|database|table|file|route|api|web|internet|youtube|publication|magazine|journal|provider|campaign|prospect)\b/i
  return explicitExecution.test(input) && target.test(input)
}

function providerFromPayload(payload: any): { provider: string | null; model: string | null } {
  const candidates = [payload?.execution, payload?.metadata, payload?.provenance, payload]
  for (const item of candidates) {
    if (!item || typeof item !== 'object') continue
    const provider = typeof item.provider === 'string' ? item.provider : typeof item.ai_provider === 'string' ? item.ai_provider : null
    const model = typeof item.model === 'string' ? item.model : typeof item.ai_model === 'string' ? item.ai_model : null
    if (provider || model) return { provider, model }
  }
  return { provider: null, model: null }
}

function authoritativeProvenance(cos: any, external: { invoked: boolean; provider?: string | null; model?: string | null }) {
  const p = cos?.provenance ?? null
  const semanticCacheHit = p?.responseSource === 'semantic_cache'
  return {
    schema_version: 1,
    authority: 'server_execution_telemetry',
    model_generated: false,
    semantic_cache: { used: semanticCacheHit, evidence_count: semanticCacheHit ? 1 : 0 },
    enterprise_memory: { used: (p?.knowledgeFactsUsed ?? 0) > 0, evidence_count: p?.knowledgeFactsUsed ?? 0 },
    knowledge_graph: { used: (p?.knowledgeFactsUsed ?? 0) > 0, evidence_count: p?.knowledgeFactsUsed ?? 0 },
    learned_corpus: { used: (p?.learnedItemsUsed ?? 0) > 0, evidence_count: p?.learnedItemsUsed ?? 0 },
    user_memory: { used: (p?.userMemoriesUsed ?? 0) > 0, evidence_count: p?.userMemoriesUsed ?? 0 },
    autonomous_research: {
      used: p?.autonomousResearchAttempted ?? false,
      documents_acquired: p?.researchDocumentsAcquired ?? 0,
      new_knowledge_retained: p?.knowledgeNewlyRetained ?? 0,
    },
    local_reasoning: {
      invoked: p?.localModelInvoked ?? false,
      model: p?.reasonerLabel ?? null,
      confidence: cos?.confidence ?? null,
      threshold: confidenceThreshold(),
    },
    external_ai: {
      invoked: external.invoked,
      provider: external.provider ?? null,
      model: external.model ?? null,
    },
  }
}

function escalationReason(cos: any, localError: string | null, requestedAction: boolean): { code: string; detail: string } {
  if (localError) return { code: 'local_reasoner_exception', detail: localError }
  if (requestedAction) return { code: 'explicit_external_action', detail: 'Delegated requested external action to governed executor.' }
  if (cos && !cos.handled) {
    const detail = String(cos.reason || 'COS declined the request without a reason.')
    if (/not configured/i.test(detail)) return { code: 'local_reasoner_not_configured', detail }
    if (/below escalation threshold/i.test(detail)) return { code: 'confidence_below_threshold', detail }
    if (/did not return an answer/i.test(detail)) return { code: 'local_reasoner_no_answer', detail }
    if (/unparseable/i.test(detail)) return { code: 'local_reasoner_unparseable', detail }
    return { code: 'cos_first_declined', detail }
  }
  return { code: 'cos_first_unavailable', detail: 'COS-first attempt unavailable.' }
}

function logEscalation(event: Record<string, unknown>) {
  console.warn('[cos-escalation-audit]', JSON.stringify({ at: new Date().toISOString(), ...event }))
}

function legacyContinuityFailure(payload: any): boolean {
  const text = JSON.stringify(payload ?? {}).toLowerCase()
  return text.includes('both reasoning providers are temporarily unavailable') || text.includes('continuity protection detected a primary failure')
}

async function independentReasonerHealth() {
  const resolved = resolveCosReasoner()
  if ('reason' in resolved) return { configured: false, healthy: false, model: null, error: resolved.reason }
  try {
    const health = await checkLocalInferenceHealth(localInferenceConfigFromEnv())
    return { configured: true, healthy: health.ok, model: health.model, error: health.error ?? null }
  } catch (error) {
    return {
      configured: true,
      healthy: false,
      model: process.env.LOCAL_AI_MODEL?.trim() || null,
      error: error instanceof Error ? error.message : String(error),
    }
  }
}

export async function POST(req: NextRequest) {
  const body = await req.clone().json().catch(() => ({}))
  const input = latestUserText(body)
  const language = languageFrom(body)
  if (!input) return legacyConciergePost(new NextRequest(req.clone()))

  const deterministic = tryDeterministicUtility({
    prompt: input,
    timezone: body?.context?.timezone || body?.context?.timeZone,
    locale: language === 'pt' ? 'pt-BR' : language === 'es' ? 'es' : language === 'pl' ? 'pl' : language === 'ru' ? 'ru' : 'en-US',
    confidenceThreshold: confidenceThreshold(),
  })
  if (deterministic) {
    return NextResponse.json({
      reply: deterministic.reply,
      source: deterministic.source,
      confidence_score: deterministic.confidence,
      confidence_threshold: confidenceThreshold(),
      external_ai_invoked: false,
      external_fallback_invoked: false,
      local_model_invoked: false,
      execution_provenance: deterministic.executionProvenance,
      execution_allowed: false,
      external_action_taken: false,
    })
  }

  const access = await getAccess().catch(() => null)
  let cos: Awaited<ReturnType<typeof tryCOSFirstAnswer>> | null = null
  let localError: string | null = null
  try {
    cos = await tryCOSFirstAnswer({ prompt: input, userId: access?.userId || null, language, privileged: Boolean(access?.isOwner || access?.isAdmin) })
  } catch (error) {
    localError = error instanceof Error ? error.message : String(error)
    console.error('[cos-local-reasoner-error]', localError)
  }

  const requestedAction = requestsExternalAction(input)
  if (cos?.handled && !requestedAction) {
    const executionProvenance = authoritativeProvenance(cos, { invoked: false })
    return NextResponse.json({
      reply: cos.reply,
      source: cos.provenance.responseSource === 'semantic_cache' ? 'cos-semantic-cache' : 'cos-local-primary',
      confidence_score: cos.confidence,
      confidence_threshold: confidenceThreshold(),
      external_ai_invoked: false,
      external_fallback_invoked: false,
      local_model_invoked: cos.provenance.localModelInvoked,
      execution_provenance: executionProvenance,
      provenance: cos.provenance,
      execution_allowed: false,
      external_action_taken: false,
    })
  }

  const reason = escalationReason(cos, localError, requestedAction)
  const auditBase = {
    event: 'external_escalation_decision',
    reason_code: reason.code,
    reason: reason.detail,
    confidence: cos?.confidence ?? null,
    threshold: confidenceThreshold(),
    local_model_invoked: cos?.provenance?.localModelInvoked ?? false,
    local_model: cos?.provenance?.reasonerLabel ?? null,
    semantic_cache_hit: cos?.provenance?.responseSource === 'semantic_cache',
    knowledge_facts_used: cos?.provenance?.knowledgeFactsUsed ?? 0,
    learned_items_used: cos?.provenance?.learnedItemsUsed ?? 0,
    external_action_requested: requestedAction,
    fallback_enabled: externalFallbackEnabled(),
  }
  logEscalation(auditBase)

  if (!externalFallbackEnabled()) {
    return NextResponse.json({
      ok: false,
      error: 'COS could not complete this request independently and external AI fallback is disabled.',
      cos_first_attempted: Boolean(cos) || Boolean(localError),
      cos_first_handled: false,
      cos_first_confidence: cos?.confidence ?? 0,
      confidence_threshold: confidenceThreshold(),
      cos_first_reason: reason.detail,
      escalation_reason_code: reason.code,
      independent_reasoner: await independentReasonerHealth(),
      external_ai_invoked: false,
      external_fallback_invoked: false,
      isolation_mode: true,
      execution_provenance: authoritativeProvenance(cos, { invoked: false }),
    }, { status: 503 })
  }

  const response = await legacyConciergePost(new NextRequest(req.clone()))
  try {
    const payload = await response.clone().json()
    const external = providerFromPayload(payload)
    const continuityFailed = legacyContinuityFailure(payload)
    const reasonerHealth = continuityFailed ? await independentReasonerHealth() : null
    logEscalation({
      event: 'external_escalation_result',
      reason_code: reason.code,
      provider: external.provider,
      model: external.model,
      status: response.status,
      continuity_failed: continuityFailed,
      independent_reasoner: reasonerHealth,
    })
    const executionProvenance = authoritativeProvenance(cos, { invoked: !continuityFailed, ...external })
    return NextResponse.json({
      ...payload,
      ...(continuityFailed ? {
        reply: `COS independent reasoning could not complete this request: ${reason.detail} External fallback was also unavailable. No action was executed.`,
        source: 'cos-independent-reasoner-unavailable',
      } : {}),
      cos_first_attempted: Boolean(cos) || Boolean(localError),
      cos_first_handled: Boolean(cos?.handled),
      cos_first_confidence: cos?.confidence ?? null,
      confidence_threshold: confidenceThreshold(),
      cos_first_reason: reason.detail,
      escalation_reason_code: reason.code,
      independent_reasoner: reasonerHealth,
      cos_first_provenance: cos?.provenance ?? null,
      execution_provenance: executionProvenance,
      external_ai_invoked: !continuityFailed,
      external_fallback_invoked: true,
      external_fallback_succeeded: !continuityFailed,
      isolation_mode: false,
    }, { status: response.status })
  } catch (error) {
    logEscalation({
      event: 'external_escalation_result_unparsed',
      reason_code: reason.code,
      provider: null,
      model: null,
      status: response.status,
      error: error instanceof Error ? error.message : String(error),
    })
    return response
  }
}
